code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    frame_boxes = []
    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        perimeter = {(r, c) for r in range(r0, r1+1) for c in range(c0, c1+1)
                     if r in (r0, r1) or c in (c0, c1)}
        if all(grid[r][c] == color for r, c in perimeter) and all(
            grid[r][c] == 0 for r in range(r0+1, r1) for c in range(c0+1, c1)):
            frame_boxes.append((color, r0, r1, c0, c1, perimeter))
    frame_cells = {p for *_, perimeter in frame_boxes for p in perimeter}
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] != 0 and (r, c) not in frame_cells)
    out = [[0]*w for _ in range(h)]
    for color, r0, r1, c0, c1, perimeter in frame_boxes:
        for r, c in perimeter:
            out[r][c] = color
        needed = sum(1 for r in range(r0+1, r1) for c in range(c0+1, c1)
                    if (r-r0-1 + c-c0-1) % 2 == 0)
        fill = next((col for col, n in counts.items() if n == needed), None)
        if fill is not None:
            for r in range(r0+1, r1):
                for c in range(c0+1, c1):
                    if (r-r0-1 + c-c0-1) % 2 == 0:
                        out[r][c] = fill
    return out
'''
